{
  "findings": [
    {
      "check_id": "CKV_AWS_100",
      "title": "Hardcoded secrets in user_data",
      "resource": "aws_launch_template.web_app",
      "severity": "CRITICAL",
      "explanation": "The user_data script contains a hardcoded API key ('sk-1234567890abcdef') and exports a database password from a variable. Hardcoded secrets in Infrastructure-as-Code are visible in state files and version control, posing a severe security risk."
    },
    {
      "check_id": "CKV_AWS_101",
      "title": "Sensitive data in user_data via variable interpolation",
      "resource": "aws_launch_template.web_app",
      "severity": "HIGH",
      "explanation": "The variable 'var.db_password' is interpolated directly into the user_data script. This exposes the secret in the Terraform state file and potentially in logs, violating best practices for secret management."
    }
  ],
  "patched_code": "resource \"aws_launch_template\" \"web_app\" {\n  name_prefix   = \"automated-employee-onboarding-platform-lt-web-\"\n  image_id      = data.aws_ami.ubuntu.id\n  instance_type = var.instance_type\n  key_name      = var.key_pair_name\n  vpc_security_group_ids = [aws_security_group.web_app.id]\n  user_data = base64encode(<<-EOF\n              # Secrets should be injected via AWS Secrets Manager or SSM Parameter Store\n              # and retrieved at runtime, not hardcoded or passed via user_data.\n              apt-get update\n              apt-get install -y nginx nodejs npm\n              systemctl start nginx\n              systemctl enable nginx\n              EOF\n  )\n  tag_specifications {\n    resource_type = \"instance\"\n  }\n}",
  "fix_summary": "Removed hardcoded API key and database password interpolation from the user_data script. Added comments indicating that secrets should be managed via AWS Secrets Manager or SSM Parameter Store and retrieved at runtime instead of being embedded in the launch template."
}
